<?php get_header(); while (have_posts()) : the_post(); $slug = get_post_field('post_name'); $sector_title = arbok_sector_name($slug); $summary = arbok_sector_summary($slug); $hero_image = has_post_thumbnail() ? get_the_post_thumbnail_url(get_the_ID(), 'large') : arbok_sector_image($slug); ?>
<section class="page-hero page-hero--compact sector-hero-v2"><div class="shell"><?php arbok_breadcrumbs(); ?><div class="inner-hero-grid"><div><p class="eyebrow">Technology sector</p><h1><?php echo esc_html($sector_title); ?></h1><p class="lede"><?php echo esc_html($summary); ?></p><div class="button-row"><a class="button" href="#sector-technologies">Related technologies</a><a class="button button-ghost" href="<?php echo esc_url(home_url('/contact/?subject=sector&sector=' . rawurlencode($sector_title))); ?>">Discuss sector</a></div></div><?php if ($hero_image) : ?><div class="inner-hero-media sector-hero-media"><img src="<?php echo esc_url($hero_image); ?>" alt="<?php echo esc_attr($sector_title); ?>"></div><?php endif; ?></div></div></section>
<?php if (trim(wp_strip_all_tags(get_the_content())) !== '') : ?><section class="section sector-content-section"><article class="shell narrow prose"><?php the_content(); ?></article></section><?php endif; ?>
<section id="sector-technologies" class="section section-soft sector-related-section"><div class="shell"><div class="section-heading"><div><p class="eyebrow dark">Related portfolio</p><h2>Technologies in <?php echo esc_html($sector_title); ?></h2></div><a class="text-link" href="<?php echo esc_url(get_post_type_archive_link('technology')); ?>">View all technologies ↗</a></div><?php $related = new WP_Query(['post_type' => 'technology', 'posts_per_page' => -1, 'tax_query' => [['taxonomy' => 'technology_sector', 'field' => 'slug', 'terms' => $slug]], 'orderby' => ['menu_order' => 'ASC', 'title' => 'ASC']]); if ($related->have_posts()) : ?><div class="grid technology-grid"><?php while ($related->have_posts()) : $related->the_post(); arbok_technology_card(); endwhile; wp_reset_postdata(); ?></div><?php else : ?><div class="empty-state"><img src="<?php echo esc_url(get_template_directory_uri() . '/assets/images/arbok-logo.png'); ?>" alt=""><h2>No technologies assigned yet.</h2><p>Add or edit a technology in WordPress and assign it to this sector to populate this page automatically.</p><a class="button button-dark" href="<?php echo esc_url(get_post_type_archive_link('technology')); ?>">View technology portfolio</a></div><?php endif; ?></div></section>
<section class="section contact-cta"><div class="shell contact-cta__inner"><img src="<?php echo esc_url(get_template_directory_uri() . '/assets/images/arbok-logo.png'); ?>" alt=""><div><p class="eyebrow">Sector discussion</p><h2>Discuss <?php echo esc_html($sector_title); ?> applications with ARBOK.</h2><div class="button-row"><a class="button" href="<?php echo esc_url(home_url('/contact/?subject=sector&sector=' . rawurlencode($sector_title))); ?>">Contact us</a><a class="button button-ghost" href="<?php echo esc_url(get_post_type_archive_link('sector')); ?>">All sectors</a></div></div></div></section>
<?php endwhile; get_footer(); ?>
